import { uid } from "./utils.js";

export function readAssessmentForm(els) {
  return {
    id: uid("assess"),
    topic: els.topic.value.trim(),
    outcomes: els.outcomes.value.trim(),
    rubric: "",
    difficulty: els.difficulty.value,
    examples: els.examples.value.trim(),
    classId: els.classSelect.value,
    status: "published",
    count: Number(els.questionCount.value),
    timeLimit: Number(els.timeLimit.value || 0),
    oralExamEnabled: els.oralExamEnabled.checked,
    disableManualTyping: els.disableManualTyping.checked,
    allowRetakes: els.allowRetakes.checked,
    maxAttempts: Number(els.maxAttempts?.value || 0),
    isTryout: els.isTryout ? els.isTryout.checked : false,
    createdAt: new Date().toISOString(),
  };
}

export function createAssessment(config, questions = []) {
  const { count, rubric, ...assessment } = config;
  // Rubrica global no se define al inicio: se deriva de las rubricas de cada
  // pregunta para que el eval/scoring continúe teniendo criterios.
  const derived = (questions || [])
    .map((q) => String(q.rubric || "").trim())
    .filter((r) => r.length > 0);
  return {
    ...assessment,
    rubric: String(rubric || "").trim() || derived.join("\n"),
    questions: questions || [],
  };
}

export function createDemoAssessment(generateQuestions) {
  const config = {
    id: uid("assess"),
    topic: "Fotosintesis dan aliran energi",
    outcomes: "Siswa mampu menjelaskan proses fotosintesis, hubungan cahaya dengan pembentukan glukosa, serta dampaknya pada ekosistem.",
    rubric: "Ketepatan konsep 40%, hubungan sebab-akibat 25%, contoh relevan 20%, kejelasan komunikasi 15%.",
    difficulty: "Menengah",
    examples: "Mengapa cahaya penting dalam proses fotosintesis?",
    count: 5,
    oralExamEnabled: true,
    disableManualTyping: false,
    allowRetakes: false,
    maxAttempts: 1,
    createdAt: new Date().toISOString(),
  };

  return createAssessment(config, generateQuestions(config));
}

export function createSubmission({
  assessment,
  studentName,
  finalScore,
  questionScores,
  feedback,
  status = "EVALUATED",
  verification = null,
  criteria = [],
  evaluationRunId = null,
  evaluationId = null,
  evaluationSource = "ai",
  insight = "",
}) {
  return {
    id: uid("sub"),
    assessmentId: assessment.id,
    assessmentTitle: assessment.topic,
    classId: assessment.classId,
    studentName,
    submittedAt: new Date().toISOString(),
    finalScore,
    questionScores,
    feedback,
    // Trustworthy-assessment metadata (PRD: score-state semantics must be explicit).
    status,
    verification,
    criteria,
    evaluationRunId,
    evaluationId,
    evaluationSource,
    insight,
  };
}
